import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { TinyUrlService } from '../../services/tiny-url.service';
import { TinyUrl } from '../../models/tiny-url.model';

@Component({
  selector: 'app-home',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './home.component.html',
  styleUrls: ['./home.component.css']
})
export class HomeComponent implements OnInit {
  inputUrl = '';
  isPrivate = false;
  isLoading = false;
  errorMsg = '';
  successMsg = '';
  private successMessageTimer: ReturnType<typeof setTimeout> | null = null;

  urls: TinyUrl[] = [];
  filteredUrls: TinyUrl[] = [];
  searchQuery = '';
  copiedCode = '';

  constructor(private tinyUrlService: TinyUrlService) {}

  ngOnInit(): void {
    this.loadUrls();
  }

  loadUrls(): void {
    this.tinyUrlService.getUrls().subscribe({
      next: (data) => {
        this.urls = data;
        this.applySearch();
      },
      error: (err) => {
        console.error('Error loading URLs', err);
        this.errorMsg = 'Could not load URLs. Make sure the API is running on http://localhost:5000.';
      }
    });
  }

  generateUrl(): void {
    this.errorMsg = '';
    this.successMsg = '';

    const originalUrl = this.inputUrl.trim();
    if (!originalUrl) {
      this.errorMsg = 'Please enter a URL.';
      return;
    }

    this.isLoading = true;

    this.tinyUrlService.createUrl({ originalUrl, isPrivate: this.isPrivate }).subscribe({
      next: (created) => {
        this.isLoading = false;
        this.successMsg = `Short URL created: ${created.shortUrl}`;
        this.clearSuccessMessageAfterDelay();
        this.inputUrl = '';
        this.isPrivate = false;
        this.urls = created.isPrivate ? this.urls : [created, ...this.urls];
        this.applySearch();
      },
      error: (err) => {
        this.isLoading = false;
        this.errorMsg = err?.error?.error || 'Failed to create URL. Use a full URL like https://example.com.';
      }
    });
  }

  deleteUrl(shortCode: string): void {
    if (!confirm(`Delete short URL "${shortCode}"?`)) return;

    this.tinyUrlService.deleteUrl(shortCode).subscribe({
      next: () => {
        this.urls = this.urls.filter((u) => u.shortCode !== shortCode);
        this.applySearch();
      },
      error: (err) => {
        console.error('Delete failed', err);
        this.errorMsg = err?.error?.error || 'Delete failed.';
      }
    });
  }

  copyToClipboard(shortUrl: string, shortCode: string): void {
    navigator.clipboard.writeText(shortUrl).then(() => {
      this.copiedCode = shortCode;
      setTimeout(() => this.copiedCode = '', 2000);
    });
  }

  trackUrlClick(clickedUrl: TinyUrl): void {
    clickedUrl.hitCount++;
  }

  applySearch(): void {
    const q = this.searchQuery.toLowerCase().trim();
    this.filteredUrls = q
      ? this.urls.filter((u) =>
          u.shortCode.toLowerCase().includes(q) ||
          u.originalUrl.toLowerCase().includes(q) ||
          u.shortUrl.toLowerCase().includes(q)
        )
      : [...this.urls];
  }

  onSearchChange(): void {
    this.applySearch();
  }

  private clearSuccessMessageAfterDelay(): void {
    if (this.successMessageTimer) {
      clearTimeout(this.successMessageTimer);
    }

    this.successMessageTimer = setTimeout(() => {
      this.successMsg = '';
      this.successMessageTimer = null;
    }, 20000);
  }
}
<div class="page-wrapper">
  <header class="header">
    <h1 class="logo">Tiny URL</h1>
  </header>

  <section class="card generator-card">
    <div class="input-row">
      <input
        type="url"
        [(ngModel)]="inputUrl"
        placeholder="Enter full URL to shorten"
        class="url-input"
        (keyup.enter)="generateUrl()"
      />
      <label class="private-toggle">
        <input type="checkbox" [(ngModel)]="isPrivate" />
        <span>Private</span>
      </label>
    </div>

    <button
      class="btn btn-primary"
      (click)="generateUrl()"
      [disabled]="isLoading"
    >
      {{ isLoading ? 'Generating...' : 'Generate' }}
    </button>

    <div *ngIf="successMsg" class="alert alert-success">{{ successMsg }}</div>
    <div *ngIf="errorMsg" class="alert alert-error">{{ errorMsg }}</div>
  </section>

  <section class="card list-card">
    <div class="list-header">
      <h2>Public URLs</h2>
      <input
        type="text"
        [(ngModel)]="searchQuery"
        (ngModelChange)="onSearchChange()"
        placeholder="Search URLs..."
        class="search-input"
      />
    </div>

    <div *ngIf="filteredUrls.length === 0" class="empty-state">
      <p>No public URLs found.</p>
    </div>

    <div class="url-list">
      <div *ngFor="let url of filteredUrls" class="url-item">
        <div class="url-info">
          <a
            [href]="url.shortUrl"
            target="_blank"
            rel="noopener"
            class="short-url"
            (click)="trackUrlClick(url)"
          >
            {{ url.shortUrl }}
          </a>
          <span class="original-url" [title]="url.originalUrl">
            {{ url.originalUrl | slice:0:60 }}{{ url.originalUrl.length > 60 ? '...' : '' }}
          </span>
        </div>

        <button
          class="btn btn-sm btn-copy"
          (click)="copyToClipboard(url.shortUrl, url.shortCode)"
        >
          {{ copiedCode === url.shortCode ? 'Copied!' : 'Copy' }}
        </button>

        <span class="clicks-badge">
          {{ url.hitCount }} click{{ url.hitCount !== 1 ? 's' : '' }}
        </span>

        <button
          class="btn btn-sm btn-delete"
          (click)="deleteUrl(url.shortCode)"
        >
          Delete
        </button>
      </div>
    </div>
  </section>
</div>
